// Two PubMed calls in one hop, so the phone makes one request instead of two.
// esearch turns a nutrient into paper ids; esummary turns those ids into
// citations. The reply keeps the upstream shapes so the app's parsing is
// unchanged. The query is biased to systematic reviews and meta-analyses
// because a single study proves very little on its own.
const q = $json.query || {};
const nutrient = String(q.nutrient || '').trim();
const limit = Math.min(Math.max(parseInt(q.limit || '3', 10) || 3, 1), 20);
if (!nutrient) { return [{ json: { ids: [], result: {}, error: 'nutrient is required' } }]; }

const E = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils';
const term = nutrient + ' supplementation AND (systematic review[pt] OR meta-analysis[pt])';

const s = await this.helpers.httpRequest({
  method: 'GET', url: E + '/esearch.fcgi', json: true,
  qs: { db: 'pubmed', retmode: 'json', sort: 'relevance', retmax: limit, term },
});
const ids = (s && s.esearchresult && s.esearchresult.idlist) || [];
if (ids.length === 0) { return [{ json: { ids: [], result: {} } }]; }

const d = await this.helpers.httpRequest({
  method: 'GET', url: E + '/esummary.fcgi', json: true,
  qs: { db: 'pubmed', retmode: 'json', id: ids.join(',') },
});
return [{ json: { ids, result: (d && d.result) || {} } }];

